WITH matched AS (SELECT a.*, sub.id AS subscription_id, sub.plan, sub.monthly_fee FROM sessions a INNER JOIN subscriptions sub ON a.customer_id = sub.customer_id AND a.started_at >= sub.start_date AND a.started_at < sub.end_date + INTERVAL '30' DAY) SELECT subscription_id, CASE WHEN subscription_id >= 8 THEN 'LARGE' ELSE 'SMALL' END AS subscription_id_tier, AVG(monthly_fee) FILTER (WHERE country = 'TH') AS th_avg_monthly_fee, MAX(started_at) AS ended_at FROM matched GROUP BY subscription_id, subscription_id_tier ORDER BY th_avg_monthly_fee ASC
